/// 翻译域的文字。按语言取实现。
pub fn translation(language: AppLanguage) -> &'static dyn TranslationStrings {
    match language {
        AppLanguage::En => &TranslationStringsEn,
        AppLanguage::Zh => &TranslationStringsZh,
        AppLanguage::Ru => &TranslationStringsRu,
        AppLanguage::Ja => &TranslationStringsJa,
        AppLanguage::Ko => &TranslationStringsKo,
        AppLanguage::Fr => &TranslationStringsFr,
        AppLanguage::De => &TranslationStringsDe,
        AppLanguage::Es => &TranslationStringsEs,
    }
}
